class AppNotification{const AppNotification({required this.id,required this.title,required this.body,required this.isRead,required this.createdAt});factory AppNotification.fromJson(Map<String,dynamic> j)=>AppNotification(id:j['id'] as String,title:j['title'] as String,body:j['body'] as String,isRead:j['isRead'] as bool,createdAt:DateTime.parse(j['createdAt'] as String).toLocal());final String id,title,body;final bool isRead;final DateTime createdAt;}